5551	async fn test_draft_title_updates_from_editor_text(cx: &mut TestAppContext) {
5552	    // When the user types into a draft, the parked draft entry's title in
5553	    // the sidebar should reflect the editor's text — both while the
5554	    // draft's `ConversationView` is still loaded (source: live message
5555	    // editor) and after it has been evicted (source: kvp draft prompt
5556	    // store, the same path used when drafts are restored from disk).
5557	    let project = init_test_project_with_agent_panel("/my-project", cx).await;
5558	    let (multi_workspace, cx) =
5559	        cx.add_window_view(|window, cx| MultiWorkspace::test_new(project.clone(), window, cx));
5560	    let (sidebar, panel) = setup_sidebar_with_agent_panel(&multi_workspace, cx);
5561	    cx.run_until_parked();
5562	
5563	    // Open an ephemeral draft via a stub connection so the conversation
5564	    // view reaches Connected synchronously and the panel's draft_thread
5565	    // pointer is populated.
5566	    let connection = StubAgentConnection::new();
5567	    agent_ui::test_support::open_draft_with_connection(&panel, connection, cx);
5568	    cx.run_until_parked();
5569	    let draft_id = panel.read_with(cx, |panel, cx| panel.active_thread_id(cx).unwrap());
5570	
5571	    // Type into the (active) draft's message editor. The helper drains the
5572	    // kvp-write debounce, so by the time it returns the prompt is on disk
5573	    // — important for Phase 2 below, which exercises the kvp fallback.
5574	    agent_ui::test_support::type_draft_prompt(&panel, "Fix the login bug", cx);
5575	
5576	    // Park the draft by pressing Cmd-N while it has content.
5577	    panel.update_in(cx, |panel, window, cx| {
5578	        panel.new_thread(&NewThread, window, cx);
5579	    });
5580	    cx.run_until_parked();
5581	
5582	    let draft_title = |sidebar: &Entity<Sidebar>, cx: &mut gpui::VisualTestContext| {
5583	        sidebar.read_with(cx, |sidebar, _cx| {
5584	            sidebar
5585	                .contents
5586	                .entries
5587	                .iter()
5588	                .find_map(|entry| match entry {
5589	                    ListEntry::Thread(thread)
5590	                        if thread.draft.is_some() && thread.metadata.thread_id == draft_id =>
5591	                    {
5592	                        Some(thread.metadata.display_title())
5593	                    }
5594	                    _ => None,
5595	                })
5596	                .expect("parked draft entry should be present")
5597	        })
5598	    };
5599	
5600	    // Phase 1: ConversationView is still loaded in `retained_threads`;
5601	    // the title comes from its live message editor.
5602	    assert_eq!(
5603	        draft_title(&sidebar, cx).as_ref(),
5604	        "Fix the login bug",
5605	        "parked draft title should match its editor text while loaded"
5606	    );
5607	    panel.read_with(cx, |panel, _cx| {
5608	        assert!(
5609	            panel.retained_threads().contains_key(&draft_id),
5610	            "draft should be in retained_threads while loaded"
5611	        );
5612	    });
5613	
5614	    // Phase 2: drop the draft's ConversationView from memory, mirroring
5615	    // the state the sidebar sees immediately after a process restart
5616	    // — the metadata row and the kvp draft prompt are on disk, but no
5617	    // ConversationView has been rehydrated yet.
5618	    let unloaded = panel.update(cx, |panel, _cx| panel.test_unload_retained_thread(draft_id));
5619	    assert!(unloaded, "draft should have been present before unload");
5620	    sidebar.update(cx, |sidebar, cx| sidebar.update_entries(cx));
5621	    cx.run_until_parked();
5622	
5623	    assert_eq!(
5624	        draft_title(&sidebar, cx).as_ref(),
5625	        "Fix the login bug",
5626	        "parked draft title should still come from the kvp draft prompt store \
5627	         even after its ConversationView is unloaded"
5628	    );
5629	}
